-- ============================================================
-- 在线帮助文档
-- ============================================================
INSERT INTO help_docs (module_name, title, content) VALUES
('dashboard',   '仪表盘帮助',   '仪表盘是系统首页，展示核心统计数据：\n\n【功能说明】\n• 顶部数据卡片：显示藏品总数、展览数量、借出中藏品、捐赠人数量等关键指标\n• 藏品分类分布图：饼图展示各分类藏品数量占比\n• 近6个月借展趋势：折线图显示借展活跃度变化\n• 近期展览列表：快速查看当前进行中和即将开始的展览\n\n【操作提示】\n点击数据卡片可跳转到对应管理页面进行详细操作。'),
('artifacts',   '藏品管理帮助', '藏品管理是系统核心模块，用于管理馆内所有文物和藏品信息。\n\n【主要功能】\n• 藏品列表：以表格形式展示所有藏品，支持分页浏览\n• 新增藏品：点击"新增藏品"按钮，填写藏品详细信息\n• 编辑藏品：点击操作列"编辑"按钮修改藏品信息\n• 删除藏品：删除前系统将检查是否有关联借展记录\n• 查看详情：点击"详情"查看藏品完整信息\n\n【搜索功能】\n支持按藏品名称（模糊）、分类、年代、保存状态进行组合查询。\n\n【注意事项】\n删除藏品时如有未归还的借展记录，系统将拒绝删除操作。'),
('donors',      '捐赠人管理帮助','捐赠人管理模块用于维护向博物馆捐赠藏品的个人、机构及企业信息。\n\n【主要功能】\n• 新增/编辑/删除捐赠人信息\n• 查看捐赠人的捐赠统计\n• 按姓名和类型搜索捐赠人\n\n【注意事项】\n已有藏品关联的捐赠人不能直接删除，需先解除藏品关联。'),
('halls',       '展馆管理帮助', '展馆管理模块用于维护博物馆各展厅的基础信息。\n\n【主要功能】\n• 管理展馆名称、位置、面积、容量等基本信息\n• 设置展馆开放状态（开放/关闭/维修中）\n• 查看展馆内当前陈列的藏品数量\n\n【状态说明】\n展馆状态会影响系统展览安排功能，维修中的展馆不能安排新展览。'),
('exhibitions', '展览管理帮助', '展览管理模块用于创建和管理博物馆的各类展览活动。\n\n【业务流程】\n筹备中 → 进行中 → 已结束\n\n【主要功能】\n• 创建展览并指定展馆、时间、策展人等信息\n• 为展览添加或移除展品（藏品）\n• 更新展览状态和参观人数\n• 查看展览详情和展品列表\n\n【注意事项】\n已取消的展览不可恢复，请谨慎操作。'),
('loans',       '借展管理帮助', '借展管理模块处理藏品外借流程，是博物馆对外交流的重要业务。\n\n【借出流程】\n1. 点击"新增借展"，填写借展机构、借展目的、归还日期等信息\n2. 选择要借出的藏品，确认藏品借出前状况\n3. 提交审批后藏品状态自动更新为"借出中"\n\n【归还流程】\n1. 在借展列表中找到"借出中"的记录\n2. 点击"办理归还"，填写实际归还日期和归还状况\n3. 确认归还后藏品状态恢复正常\n\n【逾期提醒】\n系统会自动标记超过预计归还日期未归还的借展记录为"逾期"状态。'),
('reports',     '统计报表帮助', '统计报表模块提供多维度数据分析，支持决策和管理。\n\n【报表类型】\n• 藏品分类统计：各类别藏品数量和价值分布\n• 借展统计报表：借展机构、借出时长、归还情况统计\n• 展览统计报表：各展览参观人次、展品数量对比\n• 捐赠统计报表：各捐赠人捐赠数量和价值统计\n\n【导出功能】\n点击"导出Excel"按钮可将当前报表数据导出为Excel文件，方便存档和分享。'),
('categories',  '分类管理帮助', '分类管理模块维护藏品的分类体系，支持两级分类结构。\n\n【操作说明】\n• 顶级分类：直接添加，不选择父分类\n• 子分类：添加时选择所属父分类\n• 修改分类名称不影响已关联的藏品\n\n【注意事项】\n删除分类时，已有藏品关联该分类的不能直接删除，需先修改藏品分类。'),
('users',       '用户管理帮助', '用户管理模块（仅管理员可见）用于管理系统登录账户。\n\n【角色说明】\n• admin（管理员）：拥有所有操作权限，包括删除和用户管理\n• staff（工作人员）：可进行日常藏品、展览、借展操作\n• visitor（访客）：仅可查看，不能修改数据\n\n【操作说明】\n• 新增用户：填写用户名、密码和角色\n• 重置密码：管理员可为任意用户设置新密码\n• 禁用账户：暂时禁止用户登录而不删除其数据'),
('login',       '登录帮助',     '【登录说明】\n输入用户名和密码后点击登录按钮进入系统。\n\n【默认账户】\n系统管理员账户：admin，初始密码请联系系统管理员获取。\n\n【忘记密码】\n请联系管理员重置密码。\n\n【登录失败】\n连续5次密码错误账户将被临时锁定15分钟。');
